mapper.select:
SELECT COUNT(*) FROM callevent e JOIN callsession c ON c.id=e.call_session_id WHERE
c.tenant_id=#{tenantId} AND
e.call_session_id=#{id,typeHandler=com.duozhi.outbound.common.dao.typehandler.UuidTypeHandler} AND e.event_type='dial_command_accepted' AND JSON_UNQUOTE(JSON_EXTRACT(e.payload,'$.attempt'))=#{attempt}

SELECT COUNT(*) FROM callevent e JOIN callsession c ON c.id=e.call_session_id WHERE
c.tenant_id = #{tenantId} AND c.phone = #{phone} AND e.event_type='dial_attempt_claimed' AND
e.created_at >= #{start}

SELECT * FROM `callevent` WHERE `call_session_id` IN (SELECT id FROM callsession WHERE
tenant_id = #{tenantId}) AND (call_session_id=#{p0}) ORDER BY created_at DESC LIMIT #{p1}
OFFSET #{p2}
